import * as THREE from 'three/webgpu';
import { Fn, vec2, uv, texture, mix, vec4, float } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-3-label';

  const pos = config.scenePosition || { x: 3.2, y: 1, z: 0.06 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };

  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const palette = config.visual?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const atlasInfo = config.atlasRegion || { atlas: 0, rect: [0, 0, 512, 320] };
  const [sx, sy, sw, sh] = atlasInfo.rect || [0, 0, 512, 320];

  // Plane geometry matching atlas aspect (512x320 = 1.6:1)
  const aspect = sw / sh;
  const planeW = 1.6;
  const planeH = planeW / aspect;
  const planeGeo = new THREE.PlaneGeometry(planeW, planeH, 1, 1);

  // Load texture (cached)
  const tex = ctx.textureLoader(config.assets?.imageUrl || '/prism-mock/home/nodes/feature-card.png');
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;

  // If atlas sub-region, transform UVs via offset/repeat
  const imgW = tex.image?.width || sw;
  const imgH = tex.image?.height || sh;
  if (sw !== imgW || sh !== imgH) {
    tex.repeat.set(sw / imgW, sh / imgH);
    tex.offset.set(sx / imgW, 1 - (sy + sh) / imgH);
  }

  // Engineered gradient + grain shader via TSL
  const inkColor = new THREE.Color(palette.ink);
  const surfaceColor = new THREE.Color(palette.surface);
  const paperColor = new THREE.Color(palette.paper);

  const gradientNode = Fn(([st]) => {
    const t = st.y;
    const top = vec4(surfaceColor.r, surfaceColor.g, surfaceColor.b, float(1));
    const bottom = vec4(inkColor.r, inkColor.g, inkColor.b, float(1));
    return mix(bottom, top, t);
  });

  const grainNode = Fn(([st, seed]) => {
    const n = st.x.add(st.y).mul(12.9898).add(seed).sin().mul(43758.5453);
    return n.fract().sub(0.5).mul(0.04);
  });

  const baseColor = texture(tex, uv()).rgb;
  const gradColor = gradientNode(uv());
  const grain = grainNode(uv(), float(7.3));
  const finalColor = mix(gradColor.rgb, baseColor, float(0.85)).add(grain);

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = finalColor;
  material.transparent = true;
  material.opacityNode = float(1);

  const plane = new THREE.Mesh(planeGeo, material);
  plane.name = 'collection-card-3-plane';
  group.add(plane);

  // Text label: "Collection 3" — headline role, Lora serif 400
  const textContent = config.textContent || 'Collection 3';
  const textSpec = config.textSpec || { size: 39, weight: 400, role: 'headline' };

  // Scene-unit em height: headline = 0.2 (per design tokens)
  // 39px maps to ~0.2 scene units
  const fontSize = 0.2;

  const textNode = ctx.fontAtlas(textContent, {
    font: 'Lora',
    weight: textSpec.weight || 400,
    size: fontSize,
    color: palette.paper,
    align: 'left',
    baseline: 'middle',
    letterSpacing: 0.0,
    atlas: atlasInfo.atlas ?? 0,
  });

  // Position text in lower-left area of card, like a label
  textNode.position.set(-planeW * 0.42, -planeH * 0.32, 0.001);
  textNode.name = 'collection-card-3-text';
  group.add(textNode);

  // Subtle accent underline (engineered detail)
  const underlineGeo = new THREE.PlaneGeometry(0.6, 0.012);
  const underlineMat = new THREE.MeshBasicNodeMaterial();
  underlineMat.colorNode = vec4(new THREE.Color(palette.accent).r, new THREE.Color(palette.accent).g, new THREE.Color(palette.accent).b, float(1));
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(-planeW * 0.42 + 0.3, -planeH * 0.32 - 0.13, 0.0015);
  group.add(underline);

  // Entrance animation — fade-up preset
  const timelines = [];
  group.userData.visible = true;
  group.userData.opacity = 1;

  const tl = gsap.timeline({ delay: 0.2 });
  tl.from(group.position, {
    y: pos.y + 0.2,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  tl.from(group.scale, {
    x: 0.98,
    y: 0.98,
    z: 0.98,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  timelines.push(tl);

  // Event handlers (none specified, but expose empty handlers for contract)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    timelines.length = 0;
    planeGeo.dispose();
    underlineGeo.dispose();
    material.dispose();
    underlineMat.dispose();
    if (textNode.userData?.cleanup) textNode.userData.cleanup();
    if (textNode.geometry?.dispose) textNode.geometry.dispose();
    if (textNode.material?.dispose) textNode.material.dispose();
    group.clear();
  };

  return group;
}
